<script setup lang="ts">
import { computed, ref } from 'vue'
import { api, command } from '../api'
import SchemaView from './SchemaView.vue'
import { formatFileSize } from '../recording-size.mjs'
const props = withDefaults(defineProps<{ points: any[]; captures: any[]; available?: boolean }>(), { available: true })
const emit = defineEmits<{ refresh: [] }>()
const search = ref(''), kind = ref(''), selected = ref<string[]>([]), patterns = ref('')
const filters = ref<Record<string, string>>({}), schema = ref<any>(null), error = ref(''), message = ref(''), busy = ref(false)
const files = ref<Record<string, any[]>>({})
const deleting = ref<string | null>(null), deleteFiles = ref(false)
const settings = ref({ label: 'recorder', format: 'pcapng', capacity: 256, byte_budget: 8388608, max_size: null as number | null, cycle: null as number | null })
const visible = computed(() => props.points.filter(p => p.topic.toLowerCase().includes(search.value.toLowerCase()) && (!kind.value || p.kind === kind.value)))
async function act(effect: () => Promise<any>) {
  error.value = ''; message.value = ''; busy.value = true
  try { await effect(); emit('refresh') } catch (e: any) { error.value = e.message } finally { busy.value = false }
}
function pick(id: string, checked: boolean) { selected.value = checked ? [...new Set([...selected.value, id])] : selected.value.filter(p => p !== id) }
function pointKey(point: any) { return point.point_key || point.topic }
function pointBytes(capture: any, topic: string) {
  return capture.status?.topic_bytes?.[topic] ?? (capture.state === 'DRAFT' ? 0 : undefined)
}
async function create() {
  await act(async () => {
    const selection = [...selected.value, ...patterns.value.split(/\s+/).filter(Boolean)]
    const applicableFilters = Object.fromEntries(Object.entries(filters.value).filter(([key, value]) => value && (selected.value.includes(key) || patterns.value)))
    const draft = await command('/recordings', 'POST', { ...settings.value, selection, filters: applicableFilters, kind: kind.value || undefined })
    message.value = `Draft created with ${draft.selection.length} concrete points. Review the selection below before starting.`
  })
}
async function showSchema(point: any) { await act(async () => { schema.value = await api(`/recording-points/${point.id}/schema`) }) }
async function validate(point: any) { await act(async () => { await api('/recording-filters/validate', 'POST', { point_id: point.id, expression: filters.value[point.id] }); message.value = `Filter for ${point.topic} (${point.kind}) is valid and will run at the source.` }) }
async function showFiles(capture: any) { await act(async () => { files.value[capture.id] = (await api(`/recordings/${capture.id}/files`)).items }) }
function confirmDelete(capture: any) { deleting.value = capture.id; deleteFiles.value = false }
async function remove(capture: any) {
  await act(async () => {
    const result = await command(`/recordings/${capture.id}`, 'DELETE', { delete_files: deleteFiles.value })
    delete files.value[capture.id]
    deleting.value = null
    message.value = result.files_deleted ? 'Capture and its files deleted.' : `Capture removed. Files were kept under the console state directory in ${result.retained_directory}`
  })
}
function duplicate(capture: any) {
  settings.value = { ...capture.settings }
  const resolved = capture.selection.map((s: any) => {
    const matches = props.points.filter(p => p.topic === s.topic)
    const point = matches.find(p => p.kind === (s.kind || 'output')) || (!s.kind && matches.length === 1 ? matches[0] : undefined)
    return { ...s, identity: point?.id || s.point_id || s.topic }
  })
  selected.value = resolved.map((s: any) => s.identity)
  filters.value = Object.fromEntries(resolved.map((s: any) => [s.identity, s.filter || '']))
  kind.value = ''; patterns.value = ''; message.value = 'Configuration copied into the form. Create a new draft to record again.'
}
</script>
<template>
  <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="message" class="notice" role="status">{{ message }}</p>
  <div class="workspace recording-layout"><section class="panel"><div class="section-title"><h2>Recording points</h2><span class="count">{{ points.length }}</span></div><div class="toolbar"><label class="search">Find points<input v-model="search" placeholder="Topic contains…" /></label><label>Kind<select v-model="kind"><option value="">All points</option><option>input</option><option>output</option><option>internal</option><option>external</option></select></label></div>
    <div class="points-list"><article v-for="point in visible" :key="point.id" class="point"><div class="point-title"><label class="inline"><input type="checkbox" :checked="selected.includes(point.id)" :disabled="!point.available" @change="pick(point.id, ($event.target as HTMLInputElement).checked)" /><strong>{{ point.topic }}</strong></label><button class="quiet small" @click="showSchema(point)">Schema</button></div><p class="muted small"><code>{{ point.root }}</code> · {{ point.kind }} · {{ point.available ? 'Available' : 'Unavailable' }}</p><p v-if="point.kind === 'input'" class="muted small">Value selected at tick start<span v-if="point.reception"> · {{ point.reception.buffer }}<span v-if="point.reception.buffer === 'fifo'"> · capacity {{ point.reception.capacity }}</span></span><span v-if="point.sources?.length"> · Sources: {{ point.sources.join(', ') }}</span></p><p v-if="point.description" class="small">{{ point.description }}</p><div v-if="selected.includes(point.id)" class="filter-row"><input v-model="filters[point.id]" :aria-label="`Source filter for ${point.topic} (${point.kind})`" placeholder="Optional SDL predicate, e.g. value > 10" /><button class="quiet" :disabled="!filters[point.id] || busy" @click="validate(point)">Validate</button></div></article><p v-if="!visible.length" class="empty">No matching recording points. Refresh discovery when OSE is connected.</p></div>
  </section>
  <p v-if="available === false" class="notice">Live capture controls are unavailable for this simulation. Configure captures at launch with --record. Existing console captures remain accessible below.</p><section v-if="available !== false" class="panel configuration"><h2>New capture</h2><p class="muted">Build a draft, inspect its resolved points, then start it explicitly.</p><label>Label<input v-model="settings.label" maxlength="200" /></label><p v-if="kind" class="muted small">Additional patterns use the {{ kind }} category. Checked points remain selected across categories.</p><label>Additional names, types or globs<input v-model="patterns" placeholder="sensor_*.signal Value*" /></label><div class="form-grid"><label>Format<select v-model="settings.format"><option value="pcapng">PCAPNG</option><option value="mcap">MCAP</option></select></label><label>Source queue capacity<input type="number" v-model.number="settings.capacity" min="1" max="4096" /></label><label>Source queue bytes<input type="number" v-model.number="settings.byte_budget" min="1024" /></label><label>Rotate after bytes<input type="number" :value="settings.max_size ?? ''" min="1" placeholder="Off" @input="settings.max_size = ($event.target as HTMLInputElement).value ? Number(($event.target as HTMLInputElement).value) : null" /></label><label>Retain files<input type="number" :value="settings.cycle ?? ''" min="1" placeholder="Unlimited" @input="settings.cycle = ($event.target as HTMLInputElement).value ? Number(($event.target as HTMLInputElement).value) : null" /></label></div><p v-if="settings.cycle" class="notice warning">Cyclic retention removes older capture files automatically. The rotation threshold may be exceeded by one message and closing metadata.</p><button class="primary" :disabled="busy || (!selected.length && !patterns)" @click="create">Create capture draft</button>
  </section></div>
  <section v-if="schema" class="panel detail recording-contract"><div class="section-title"><h2>Recording contract</h2><button class="quiet" @click="schema = null">Close</button></div><SchemaView :schema="schema" /></section>
  <section class="panel capture-list"><div class="section-title"><h2>Captures</h2><span class="muted">Captures continue when the browser closes.</span></div><p v-if="!captures.length" class="empty">No captures yet.</p><article v-for="capture in [...captures].reverse()" :key="capture.id" class="capture"><div class="section-title"><div><h3>{{ capture.settings.label }}</h3><small class="mono muted">{{ capture.id.slice(0, 12) }} · {{ capture.settings.format.toUpperCase() }} · {{ capture.owner }}</small></div><span class="badge" :data-state="capture.state === 'FAILED' ? 'error' : capture.state === 'RECORDING' ? 'ok' : 'idle'">{{ capture.state }}</span></div><p v-if="capture.error" class="notice error">{{ capture.error }}</p><p v-if="capture.storage_warning" class="notice warning">{{ capture.storage_warning }}</p><div class="capture-counts"><span class="capture-file-size" :title="capture.status?.file_size_bytes == null ? 'Size unavailable' : `${capture.status.file_size_bytes} bytes on disk`"><strong>{{ formatFileSize(capture.status?.file_size_bytes) }}</strong> current file size</span><span><strong>{{ capture.status?.counts?.written || 0 }}</strong> messages written</span><span><strong>{{ capture.status?.capture_counts?.dropped || 0 }}</strong> source drops</span><span><strong>{{ capture.status?.counts?.filtered || 0 }}</strong> filtered</span><span><strong>{{ capture.status?.file_count || 0 }}</strong> files retained</span></div><details :open="capture.state === 'DRAFT'"><summary>{{ capture.selection.length }} concrete points</summary><ul class="point-selection"><li v-for="point in capture.selection" :key="pointKey(point)"><code>{{ point.topic }}</code> · {{ point.kind || 'output' }} · {{ point.root }}<span v-if="point.filter"> · filter: <code>{{ point.filter }}</code></span><span class="point-recording-stats"><span class="point-recording-count"><strong>{{ capture.status?.topics?.[pointKey(point)] ?? 0 }}</strong> recorded</span><span class="point-recording-size" title="Cumulative encoded SDL message bytes recorded for this point"><strong>{{ formatFileSize(pointBytes(capture, pointKey(point))) }}</strong> recorded data</span></span></li></ul></details><div class="actions"><button v-if="available && capture.state === 'DRAFT'" class="primary" :disabled="busy" @click="act(() => command(`/recordings/${capture.id}/start`))">Start capture</button><button v-if="['STARTING','RECORDING','STOPPING'].includes(capture.state)" class="danger" :disabled="busy" @click="act(() => command(`/recordings/${capture.id}/stop`))">Stop and finalize</button><button v-if="available" class="quiet" @click="duplicate(capture)">Duplicate configuration</button><button v-if="['STOPPED','FAILED','INTERRUPTED'].includes(capture.state)" class="quiet" @click="showFiles(capture)">Show files</button><button v-if="['DRAFT','STOPPED','FAILED','INTERRUPTED'].includes(capture.state) && capture.permissions?.delete" class="danger" :disabled="busy" @click="confirmDelete(capture)">Delete</button></div><section v-if="deleting === capture.id && ['DRAFT','STOPPED','FAILED','INTERRUPTED'].includes(capture.state)" class="notice" role="dialog" aria-label="Delete capture"><h3>Delete this capture?</h3><p>Remove “{{ capture.settings.label }}” from the capture list. This cannot be undone.</p><label>Capture files<select v-model="deleteFiles" :disabled="busy"><option :value="false">Keep files on disk</option><option :value="true">Delete files permanently</option></select></label><p class="small">{{ deleteFiles ? 'The capture files will be permanently removed from disk.' : 'Files will remain on disk, but will no longer be available through this console.' }}</p><div class="actions"><button class="quiet" :disabled="busy" @click="deleting = null">Cancel</button><button class="danger" :disabled="busy" @click="remove(capture)">{{ deleteFiles ? 'Delete capture and files' : 'Delete capture' }}</button></div></section><div v-if="files[capture.id]" class="table-scroll"><table><thead><tr><th>File</th><th>Size</th><th>Integrity</th><th>Actions</th></tr></thead><tbody><tr v-for="file in files[capture.id]" :key="file.id"><td>{{ file.name }}<small v-if="capture.state === 'INTERRUPTED'">Interrupted artifact</small></td><td :title="file.size == null ? 'Size unavailable' : `${file.size} bytes`">{{ formatFileSize(file.size) }}</td><td>{{ file.expired ? 'Expired' : file.integrity }}</td><td><a v-if="!file.expired" :href="`/api/v1/files/${file.id}/download`">Download</a><button v-if="!file.expired" class="quiet small" :disabled="busy" @click="act(async () => { await command(`/files/${file.id}/validate`); await showFiles(capture) })">Validate file</button></td></tr></tbody></table><p v-if="!files[capture.id].length" class="muted">No retained files.</p></div></article></section>
</template>
